"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";

import { IconClose } from "@rhs-ui/icons";
import {
  countPageView,
  isBusy,
  isSuppressed,
  isTyping,
  localStorageSuppression,
  scrollDepth,
  type NewsletterDismissal,
  type NewsletterLabels,
  type NewsletterStorage,
  type NewsletterTrigger,
} from "@rhs-ui/application/newsletter-dialog/newsletter";
import { NewsletterPanel } from "@rhs-ui/application/newsletter-dialog/panel";
import { Dialog, DialogClose, DialogContent } from "@rhs-ui/primitives/dialog";
import { cn } from "@/lib/utils";

export type { NewsletterDismissal, NewsletterLabels, NewsletterStorage, NewsletterTrigger } from "@rhs-ui/application/newsletter-dialog/newsletter";
export { NewsletterPanel, type NewsletterPanelProps } from "@rhs-ui/application/newsletter-dialog/panel";

export interface NewsletterDialogProps {
  /** Signs the address up. Return a promise: the field locks and the button shows progress while it runs and the dialog cannot be closed; a rejection keeps the address and shows the message; success replaces the form with a confirmation. */
  onSubscribe: (email: string) => void | Promise<void>;
  /** When it opens by itself: "delay" after `delayMs`, "scroll" at `scrollDepth`, or "manual" never (you open it with `open`). Default "delay". */
  trigger?: NewsletterTrigger;
  /** For "delay": how long after the page loads, in milliseconds. Default 20000. */
  delayMs?: number;
  /** For "scroll": how far down the page, as a percentage of its height. Default 60. */
  scrollDepth?: number;
  /** How many days it keeps away after a dismissal (and after a sign-up). Default 30. */
  suppressDays?: number;
  /** Called when it is dismissed, with how: "decline" (No thanks), "close" (the corner button), "escape" or "outside". The moment is stored first. */
  onDismiss?: (reason: NewsletterDismissal) => void;
  /** Where the moment of the last dismissal is kept: `{ read, write }`. Default: localStorage. Use a cookie, or your own store, by passing your own pair; `read` may return `Infinity` for someone who must never be asked. */
  storage?: NewsletterStorage;
  /** A line about what people get, in place of the default description: "One email a week: what we shipped, what we learned." */
  incentive?: string;
  /** How many pages the visitor has seen in this session, if you count them (a router can). Default: the pages this component has been on in this tab's session, so it never opens on the first. */
  pageViews?: number;
  /** The least number of pages in the session before it may open. Default 2: never on the first page view. */
  minPageViews?: number;
  /** Whether the dialog is open, when you control it. A controlled dialog never opens by itself. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. A close that is refused while the sign-up is on its way is not reported. */
  onOpenChange?: (open: boolean) => void;
  /** The words the dialog says, for translation. */
  labels?: NewsletterLabels;
  /** Classes for the dialog panel, for a different width. */
  className?: string;
}

/** How often to look again when somebody is in the middle of something. */
const RETRY_MS = 1500;

/**
 * A newsletter invitation with the manners of a good guest. It opens after a delay or a depth of scrolling, and only when
 * it is welcome: never on the first page view of a session, never while somebody is typing in a field or another dialog is
 * open, never in a background tab, and never again inside `suppressDays` after it was dismissed or answered. It asks for one
 * email with a plain line about privacy; Escape, the corner button, "No thanks" and a click outside are all as easy as
 * Subscribe, and success replaces the form in place and closes after a moment, with focus going back to whatever had it when it
 * opened. `storage` is a pair of functions, so you choose where "not again" is remembered.
 */
export function NewsletterDialog({
  onSubscribe,
  trigger = "delay",
  delayMs = 20_000,
  scrollDepth: depth = 60,
  suppressDays = 30,
  onDismiss,
  storage = localStorageSuppression,
  incentive,
  pageViews,
  minPageViews = 2,
  open,
  defaultOpen = false,
  onOpenChange,
  labels,
  className,
}: NewsletterDialogProps) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const [busy, setBusy] = useState(false);
  const busyNow = useRef(false);
  const reason = useRef<NewsletterDismissal | null>(null);
  const answered = useRef(false);
  const counted = useRef<number | null>(null);
  const content = useRef<HTMLDivElement>(null);
  const returnTo = useRef<HTMLElement | null>(null);
  const latest = useRef({ storage, onDismiss, onOpenChange, open });
  useEffect(() => {
    latest.current = { storage, onDismiss, onOpenChange, open };
  });
  const isOpen = open ?? ownOpen;
  const auto = trigger !== "manual" && open === undefined;

  // There is no DialogTrigger here, so the dialog has nowhere of its own to give focus back to: it remembers who had it at the moment it
  // opened (the visitor's own button, or a link they were on), before the dialog takes focus into itself.
  useLayoutEffect(() => {
    if (!isOpen) return;
    const active = document.activeElement;
    returnTo.current = active instanceof HTMLElement && active !== document.body ? active : null;
  }, [isOpen]);

  function change(next: boolean) {
    // A sign-up that is on its way cannot be walked away from.
    if (!next && busyNow.current) return;
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
    if (next) return;
    // Anything but a sign-up that worked is a "not now": remember it, and say how it happened.
    if (!answered.current) {
      storage.write(Date.now());
      onDismiss?.(reason.current ?? "close");
    }
    reason.current = null;
  }

  // The moment to open: found by the delay or by the scrolling, and then only if it is welcome.
  useEffect(() => {
    if (!auto) return;
    // Counted once per mount, so React's strict mode (which runs this twice) does not make a first view look like a second.
    counted.current ??= countPageView();
    const views = pageViews ?? counted.current;
    if (views < minPageViews || isSuppressed(latest.current.storage, suppressDays, Date.now())) return;

    let retry: number | undefined;
    let waiting = true;
    const welcome = () => {
      window.clearTimeout(retry);
      if (!waiting) return;
      // Looked at again at the very last moment: another tab may have been dismissed while this one waited.
      if (isTyping() || isBusy()) {
        retry = window.setTimeout(welcome, RETRY_MS);
        return;
      }
      if (isSuppressed(latest.current.storage, suppressDays, Date.now())) return;
      waiting = false;
      setOwnOpen(true);
      latest.current.onOpenChange?.(true);
    };

    let cleanup = () => {};
    if (trigger === "delay") {
      const timer = window.setTimeout(welcome, delayMs);
      cleanup = () => window.clearTimeout(timer);
    } else {
      const check = () => {
        if (scrollDepth() < depth) return;
        window.removeEventListener("scroll", check);
        welcome();
      };
      window.addEventListener("scroll", check, { passive: true });
      check();
      cleanup = () => window.removeEventListener("scroll", check);
    }
    return () => {
      waiting = false;
      window.clearTimeout(retry);
      cleanup();
    };
  }, [auto, trigger, delayMs, depth, suppressDays, pageViews, minPageViews]);

  return (
    <Dialog open={isOpen} onOpenChange={change}>
      <DialogContent
        ref={content}
        data-slot="newsletter-dialog"
        showCloseButton={false}
        onEscapeKeyDown={() => {
          reason.current = "escape";
        }}
        onPointerDownOutside={() => {
          reason.current = "outside";
        }}
        onCloseAutoFocus={(event) => {
          // Back to whoever had focus when it opened, if they are still on the page; without a trigger Radix would leave focus on the document.
          event.preventDefault();
          const back = returnTo.current;
          returnTo.current = null;
          if (back?.isConnected) back.focus({ preventScroll: true });
        }}
        onOpenAutoFocus={(event) => {
          // A dialog nobody asked for does not raise the keyboard on a phone: on a touch screen focus rests on the dialog until a finger goes to the field.
          if (typeof window.matchMedia === "function" && window.matchMedia("(pointer: coarse)").matches) {
            event.preventDefault();
            content.current?.focus({ preventScroll: true });
          }
        }}
        className={cn("flex max-h-[calc(100dvh-2rem)] flex-col gap-0 overflow-hidden p-0 sm:max-w-md", className)}
      >
        <NewsletterPanel
          onSubscribe={onSubscribe}
          incentive={incentive}
          labels={labels}
          onDecline={() => {
            reason.current = "decline";
          }}
          onSubscribed={() => {
            // Someone who signed up is not asked again for the same days as someone who said no.
            answered.current = true;
            storage.write(Date.now());
          }}
          onClose={() => change(false)}
          onBusyChange={(next) => {
            busyNow.current = next;
            setBusy(next);
          }}
        />
        <DialogClose asChild>
          <button
            type="button"
            disabled={busy}
            aria-label={labels?.closeIcon ?? "Close"}
            onClick={() => {
              reason.current = "close";
            }}
            // Level with the title: the header starts 8px lower from sm up (sm:pt-6), and the button goes down with it.
            className="absolute top-[1.1rem] right-4 inline-flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors duration-150 outline-none hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 disabled:pointer-events-none disabled:opacity-50 sm:top-[1.4rem]"
          >
            <IconClose size={16} />
          </button>
        </DialogClose>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";

import { IconAlertCircle, IconMail, IconSpinner } from "@rhs-ui/icons";
import { DEFAULT_LABELS, fill, isEmail, messageOf, type NewsletterLabels } from "@rhs-ui/application/newsletter-dialog/newsletter";
import { Alert, AlertDescription, AlertTitle } from "@rhs-ui/primitives/alert";
import { Button } from "@rhs-ui/primitives/button";
import { DialogClose, DialogDescription, DialogTitle } from "@rhs-ui/primitives/dialog";
import { FormControl, FormDescription, FormField, FormLabel } from "@rhs-ui/primitives/form-field";
import { Input } from "@rhs-ui/primitives/input";
import { ResultState } from "@rhs-ui/primitives/result-state";
import { cn } from "@/lib/utils";

export interface NewsletterPanelProps {
  /** Signs the address up. Return a promise: the field locks and the button shows progress while it runs, a rejection keeps the address and shows the message, and success replaces the form with the confirmation. */
  onSubscribe: (email: string) => void | Promise<void>;
  /** A line about what people get, in place of the default description: "One email a week: what we shipped, what we learned." */
  incentive?: string;
  /** The email the field starts with, such as the signed-in person's. */
  defaultEmail?: string;
  /** Called when "No thanks" is pressed. Inside a Dialog the button closes it and the dialog reports the dismissal. */
  onDecline?: () => void;
  /** Called once the sign-up worked, with the address. */
  onSubscribed?: (email: string) => void;
  /** How long the confirmation stays, in milliseconds, before `onClose` is called. A bar runs down while it waits, and it holds still while keyboard focus is on its button. 0 keeps it until it is closed. Default 3000. */
  closeAfterMs?: number;
  /** Draw the panel on its own (a page, a sheet, a preview) instead of inside a Dialog. The title is then a plain heading. */
  standalone?: boolean;
  /** Called when the confirmation closes itself, and when "Close" is pressed in a standalone panel. Inside a Dialog the button closes it. */
  onClose?: () => void;
  /** Called with true while the sign-up is on its way and false after, so a dialog around the panel can refuse to close in the meantime. */
  onBusyChange?: (busy: boolean) => void;
  /** The words the panel says, for translation. */
  labels?: NewsletterLabels;
  /** Classes for the panel. */
  className?: string;
}

function Heading({ standalone, className, children }: { standalone: boolean; className: string; children: ReactNode }) {
  return standalone ? <h2 className={className}>{children}</h2> : <DialogTitle className={className}>{children}</DialogTitle>;
}

function Lede({ standalone, className, children }: { standalone: boolean; className: string; children: ReactNode }) {
  return standalone ? <p className={className}>{children}</p> : <DialogDescription className={className}>{children}</DialogDescription>;
}

/** A line that runs down while the confirmation waits to close. It is the clock itself: the animation finishing is what calls `onDone`. */
function Countdown({ ms, paused, onDone }: { ms: number; paused: boolean; onDone: () => void }) {
  const bar = useRef<HTMLSpanElement>(null);
  const run = useRef<Animation | null>(null);
  const finish = useRef(onDone);
  useEffect(() => {
    finish.current = onDone;
  });
  useEffect(() => {
    const element = bar.current;
    if (!element || typeof element.animate !== "function") return;
    const animation = element.animate([{ transform: "scaleX(1)" }, { transform: "scaleX(0)" }], { duration: ms, easing: "linear", fill: "forwards" });
    animation.onfinish = () => finish.current();
    run.current = animation;
    return () => {
      animation.cancel();
      run.current = null;
    };
  }, [ms]);
  useEffect(() => {
    const animation = run.current;
    if (!animation || animation.playState === "finished") return;
    if (paused) animation.pause();
    else animation.play();
  }, [paused]);
  return (
    <span aria-hidden="true" className="block h-0.5 w-full max-w-56 overflow-hidden rounded-full bg-border motion-reduce:hidden">
      <span ref={bar} className="block h-full origin-left bg-foreground/50" />
    </span>
  );
}

/**
 * The inside of the newsletter dialog, on its own: one email field with a plain line about privacy, and two answers that are
 * equally easy to find, Subscribe and "No thanks". Subscribing locks the field and shows progress on the button, a failure keeps
 * the address and says what happened, and success replaces the form in place with a confirmation that closes by itself. Use it
 * inside a Dialog, or with `standalone` anywhere else.
 */
export function NewsletterPanel({
  onSubscribe,
  incentive,
  defaultEmail = "",
  onDecline,
  onSubscribed,
  closeAfterMs = 3000,
  standalone = false,
  onClose,
  onBusyChange,
  labels,
  className,
}: NewsletterPanelProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const [email, setEmail] = useState(defaultEmail);
  const [status, setStatus] = useState<"idle" | "pending" | "done">("idle");
  const [error, setError] = useState<string | null>(null);
  const [problem, setProblem] = useState<string | null>(null);
  const [held, setHeld] = useState(false);
  const [sentTo, setSentTo] = useState("");
  const field = useRef<HTMLInputElement>(null);
  const submitButton = useRef<HTMLButtonElement>(null);
  const confirmation = useRef<HTMLDivElement>(null);
  const busy = useRef(false);
  const pending = status === "pending";

  useEffect(() => {
    if (status === "done") confirmation.current?.focus({ preventScroll: true });
  }, [status]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    // A dialog is drawn in a portal, but React still passes its events up to whatever rendered it: do not submit a form around it as well.
    event.stopPropagation();
    if (busy.current) return;
    if (!isEmail(email)) {
      setProblem(words.invalid);
      field.current?.focus({ preventScroll: true });
      return;
    }
    busy.current = true;
    setError(null);
    setProblem(null);
    setStatus("pending");
    onBusyChange?.(true);
    // The field is about to switch off and take the focus with it. The button stays focusable, so focus rests there while it is sent.
    submitButton.current?.focus({ preventScroll: true });
    try {
      await onSubscribe(email.trim());
      setSentTo(email.trim());
      setStatus("done");
      onSubscribed?.(email.trim());
    } catch (thrown) {
      setStatus("idle");
      setError(messageOf(thrown) ?? words.failedBody);
      window.requestAnimationFrame(() => field.current?.focus({ preventScroll: true }));
    } finally {
      busy.current = false;
      onBusyChange?.(false);
    }
  }

  if (status === "done") {
    return (
      <div
        ref={confirmation}
        tabIndex={-1}
        data-slot="newsletter-panel"
        data-status="done"
        // While keyboard focus is on the button, the clock holds still; focus on the confirmation itself does not count.
        onFocusCapture={(event) => setHeld(event.target !== event.currentTarget)}
        onBlurCapture={() => setHeld(false)}
        className={cn("grid outline-none", className)}
      >
        <Heading standalone={standalone} className="sr-only">
          {words.done}
        </Heading>
        <Lede standalone={standalone} className="sr-only">
          {fill(words.doneBody, { email: sentTo })}
        </Lede>
        <p role="status" className="sr-only">
          {words.done}
        </p>
        <ResultState
          tone="success"
          title={words.done}
          description={fill(words.doneBody, { email: sentTo })}
          className="px-5 py-10 sm:px-6 sm:py-12"
          actions={
            <>
              {standalone ? (
                <Button type="button" variant="outline" onClick={onClose}>
                  {words.close}
                </Button>
              ) : (
                <DialogClose asChild>
                  <Button type="button" variant="outline">
                    {words.close}
                  </Button>
                </DialogClose>
              )}
              {closeAfterMs > 0 ? (
                <div className="mt-3 grid basis-full justify-items-center gap-2">
                  <Countdown ms={closeAfterMs} paused={held} onDone={() => onClose?.()} />
                  <p className="text-xs text-muted-foreground">{words.closing}</p>
                </div>
              ) : null}
            </>
          }
        />
      </div>
    );
  }

  return (
    <form data-slot="newsletter-panel" data-status={status} noValidate onSubmit={(event) => void submit(event)} className={cn("flex min-h-0 flex-col", className)}>
      <div className="flex shrink-0 items-start gap-3.5 px-5 pt-5 pr-14 pb-4 sm:px-6 sm:pt-6">
        <span aria-hidden="true" className="grid size-10 shrink-0 place-items-center rounded-xl border border-border bg-muted text-foreground [&_svg]:size-[1.125rem]">
          <IconMail />
        </span>
        <div className="grid min-w-0 gap-1 pt-px">
          <Heading standalone={standalone} className="text-lg leading-tight font-semibold tracking-[-0.02em]">
            {words.title}
          </Heading>
          <Lede standalone={standalone} className="text-sm leading-relaxed text-muted-foreground">
            {incentive ?? words.description}
          </Lede>
        </div>
      </div>

      {/* The body scrolls when the dialog is shorter than its content (a phone on its side, larger text, the failure message), and the header and the buttons stay where they are. */}
      <div className="relative min-h-0 flex-1 overflow-y-auto px-5 pb-6 sm:px-6">
        {error !== null ? (
          <Alert tone="destructive" role="alert" className="mb-4 text-[color-mix(in_oklch,var(--destructive),var(--foreground)_20%)]">
            <IconAlertCircle />
            <AlertTitle>{words.failed}</AlertTitle>
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        ) : null}
        <fieldset disabled={pending} className="m-0 grid min-w-0 border-0 p-0">
          <FormField error={problem} described className="gap-1.5">
            <FormLabel>{words.email}</FormLabel>
            <FormControl>
              <Input
                ref={field}
                type="email"
                autoComplete="email"
                inputMode="email"
                value={email}
                placeholder={words.placeholder}
                onChange={(event) => {
                  setEmail(event.target.value);
                  if (problem) setProblem(null);
                }}
              />
            </FormControl>
            <FormDescription>{words.privacy}</FormDescription>
          </FormField>
        </fieldset>
      </div>

      <div className="flex shrink-0 flex-col-reverse gap-2 border-t border-border bg-muted/30 px-5 py-4 sm:flex-row sm:justify-end sm:px-6">
        {standalone ? (
          <Button type="button" variant="outline" disabled={pending} onClick={onDecline}>
            {words.decline}
          </Button>
        ) : (
          <DialogClose asChild>
            <Button type="button" variant="outline" disabled={pending} onClick={onDecline}>
              {words.decline}
            </Button>
          </DialogClose>
        )}
        {/* Busy is said with aria-busy and aria-disabled, not disabled: a disabled button gives up focus, which would leave a keyboard on no control until the sign-up is done. */}
        <Button ref={submitButton} type="submit" aria-busy={pending || undefined} aria-disabled={pending || undefined} className="aria-disabled:cursor-progress">
          {pending ? <IconSpinner data-slot="button-spinner" /> : null}
          {words.subscribe}
        </Button>
      </div>
      <p role="status" className="sr-only">
        {pending ? words.subscribing : ""}
      </p>
    </form>
  );
}

/**
 * The manners of the newsletter dialog as plain functions with no hook: when it may open, what it remembers, and the
 * checks it makes before it speaks. The component calls them; a Server Component can use the words and the labels too.
 */

/** How the dialog finds its moment: a delay after the page loads, a depth of scrolling, or never by itself (you open it). */
export type NewsletterTrigger = "delay" | "scroll" | "manual";

/** Why the dialog was dismissed, so you can tell a "No thanks" from a stray Escape. */
export type NewsletterDismissal = "decline" | "close" | "escape" | "outside";

/**
 * Where the moment of the last dismissal is kept. `read` returns when it was (milliseconds since 1970) or nothing; `write` is
 * given the moment to keep. A cookie, localStorage, your own database: you choose. `read` may return `Infinity` for a visitor
 * who must never be asked again, such as one who is already subscribed.
 */
export interface NewsletterStorage {
  read: () => number | null | undefined;
  write: (at: number) => void;
}

/** The words the dialog says, for translation. Use `{email}` where the default does. */
export interface NewsletterLabels {
  /** The title. Default "Stay in the loop". */
  title?: string;
  /** The line under it when you give no `incentive`. Default "New posts and product news in your inbox. No spam, and you can leave at any time." */
  description?: string;
  /** The label of the email field. Default "Email address". */
  email?: string;
  /** The hint in the field. Default "you@company.com". */
  placeholder?: string;
  /** The plain line about privacy under the field. Default "We use your email for this newsletter only, and every email has a one-click unsubscribe." */
  privacy?: string;
  /** The button that subscribes. Default "Subscribe". */
  subscribe?: string;
  /** The button that says no, as easy to find as the other. Default "No thanks". */
  decline?: string;
  /** Said while the sign-up is on its way. Default "Subscribing". */
  subscribing?: string;
  /** What is said when the address is not one. Default "Enter a valid email address." */
  invalid?: string;
  /** The heading of the message after a failure. Default "Could not subscribe you". */
  failed?: string;
  /** The message when the failure carries none. Default "Something went wrong on our side. Your address is still here, so you can try again." */
  failedBody?: string;
  /** The title once it worked. Default "You're subscribed". */
  done?: string;
  /** The line under it. Default "We sent a confirmation to {email}. Open it to finish." */
  doneBody?: string;
  /** Said under the bar that runs down. Default "This window closes by itself." */
  closing?: string;
  /** The button on the confirmation. Default "Close". */
  close?: string;
  /** The name of the corner button. Default "Close". */
  closeIcon?: string;
}

export const DEFAULT_LABELS = {
  title: "Stay in the loop",
  description: "New posts and product news in your inbox. No spam, and you can leave at any time.",
  email: "Email address",
  placeholder: "you@company.com",
  privacy: "We use your email for this newsletter only, and every email has a one-click unsubscribe.",
  subscribe: "Subscribe",
  decline: "No thanks",
  subscribing: "Subscribing",
  invalid: "Enter a valid email address.",
  failed: "Could not subscribe you",
  failedBody: "Something went wrong on our side. Your address is still here, so you can try again.",
  done: "You're subscribed",
  doneBody: "We sent a confirmation to {email}. Open it to finish.",
  closing: "This window closes by itself.",
  close: "Close",
  closeIcon: "Close",
} satisfies Required<NewsletterLabels>;

/** Puts values into a template: `fill("Sent to {email}", { email })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match));
}

/** A deliberately plain check: something, an @, something, a dot, something. The server is the judge of the rest. */
export function isEmail(value: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

/** The words of whatever was thrown: a string, or the message of an error or of any object that has one. */
export function messageOf(thrown: unknown): string | null {
  const text = typeof thrown === "string" ? thrown : (thrown as { message?: unknown } | null | undefined)?.message;
  return typeof text === "string" && text.trim() ? text : null;
}

const DAY = 86_400_000;

/** The key under which the default storage keeps the moment of the last dismissal. */
export const DISMISSED_KEY = "rhs-newsletter-dismissed";

/** The key under which the number of pages seen in this tab's session is kept. */
export const VIEWS_KEY = "rhs-newsletter-views";

/** The default storage: the moment in localStorage. Where that is blocked it remembers nothing, and the dialog stays shy rather than rude. */
export const localStorageSuppression: NewsletterStorage = {
  read() {
    try {
      const value = Number(window.localStorage.getItem(DISMISSED_KEY));
      return Number.isFinite(value) && value > 0 ? value : null;
    } catch {
      return null;
    }
  },
  write(at) {
    try {
      window.localStorage.setItem(DISMISSED_KEY, String(at));
    } catch {
      // storage is blocked: nothing to remember it with
    }
  },
};

/** Whether the last dismissal is still inside the days the dialog keeps away. */
export function isSuppressed(storage: NewsletterStorage, days: number, now: number): boolean {
  const at = storage.read();
  return typeof at === "number" && !Number.isNaN(at) && now - at < days * DAY;
}

/**
 * Counts this page as seen in the session and says how many have been. Where sessionStorage is blocked it says 1 whatever the
 * number, so the dialog never opens on a page it cannot be sure is not the first.
 */
export function countPageView(): number {
  try {
    const next = Number(window.sessionStorage.getItem(VIEWS_KEY) ?? "0") + 1;
    window.sessionStorage.setItem(VIEWS_KEY, String(next));
    return next;
  } catch {
    return 1;
  }
}

/** Whether somebody is in the middle of a field: focus is in something they type into. */
export function isTyping(): boolean {
  const active = document.activeElement;
  if (!(active instanceof HTMLElement)) return false;
  if (active.isContentEditable) return true;
  if (active instanceof HTMLTextAreaElement || active instanceof HTMLSelectElement) return true;
  return active instanceof HTMLInputElement && !["button", "checkbox", "radio", "range", "submit", "reset", "file", "image", "color"].includes(active.type);
}

/** Whether something else already has the visitor's attention: another dialog is open, or the tab is in the background. */
export function isBusy(): boolean {
  if (document.visibilityState === "hidden") return true;
  return document.querySelector('[role="dialog"][data-state="open"], [role="alertdialog"][data-state="open"], dialog[open]') !== null;
}

/** How far down the page the visitor has seen, as a percentage of its height. */
export function scrollDepth(): number {
  const height = Math.max(document.documentElement.scrollHeight, document.body.scrollHeight);
  if (height <= 0) return 0;
  return Math.min(100, ((window.scrollY + window.innerHeight) / height) * 100);
}
